#!/usr/bin/env python3
"""Independent ETW capture ownership: hardware microphone is not render loopback."""
import argparse,hashlib,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('trial',type=Path);p.add_argument('output',type=Path);a=p.parse_args()
r=json.loads((a.trial/'artifacts/report.json').read_text());e=json.loads((a.trial/'normalized.json').read_text(encoding='utf-8-sig'));policy=json.loads((a.trial/'trial-policy.json').read_text(encoding='utf-8-sig'));sdk=json.loads((a.trial/'sdk-manifest.json').read_text(encoding='utf-8-sig'))
mods=lambda event:{f.get('module','').lower() for f in event.get('stack',[])}
starts={q['data'].get('AudioClientGuidId') for q in e['events'] if q['event']=='AudioClientStart' and q['data'].get('HResult')=='0x00000000'}
clients=[]
for q in e['events']:
 if q['event']!='AudioClientInitialize':continue
 data=q['data'];m=mods(q);kind='render-loopback' if data.get('StreamType')=='2' else 'speaker' if data.get('StreamType')=='0' else 'sdk-microphone' if 'libwebrtc.dll' in m else 'record-raw-microphone' if 'record_windows_plugin.dll' in m else 'unknown-microphone'
 clients.append({'kind':kind,'modules':sorted(m),'endpointSha256':data.get('EndpointIdSha256'),'streamType':data.get('StreamType'),'streamFlags':data.get('StreamFlags'),'rawRequested':data.get('RawStreamRequested'),'initialize':data.get('HResult'),'started':data.get('AudioClientGuidId') in starts,'stackAvailable':bool(q.get('stack')),'rate':data.get('SampleRate'),'channels':data.get('NumberOfChannels')})
raw=[c for c in clients if c['kind']=='record-raw-microphone'];sdkmic=[c for c in clients if c['kind']=='sdk-microphone'];loop=[c for c in clients if c['kind']=='render-loopback' and 'aec_audio_plugin.dll' in c['modules']];speaker=[c for c in clients if c['kind']=='speaker' and 'libwebrtc.dll' in c['modules']]
record=r.get('stoppedStats',{}).get('recordRawAudit',{});frames=r.get('stoppedStats',{}).get('captureSamples',0)
identity=json.loads((a.trial/'runtime-module.json').read_text(encoding='utf-8-sig'));rawok=record.get('rawRequests')==record.get('rawPropertiesAccepted')==record.get('rawStarts')==1 and record.get('mfCreateRequests')==record.get('activeRawCaptures')==record.get('lastHresult')==0 and record.get('nativeCaptureFrames',0)>0
zero=bool(not r['errors'] and policy['externalOnly'] and len(raw)==1 and len(sdkmic)==0 and len(loop)==1 and len(speaker)==1 and all(c['stackAvailable'] and c['initialize']=='0x00000000' and c['started'] for c in raw+loop+speaker) and not any(c['kind']=='unknown-microphone' for c in clients) and e['lostEvents']==e['lostBuffers']==0 and rawok and frames>0 and identity.get('sha256')==sdk['dllSha256'])
result={'session':policy['session'],'externalOnly':policy['externalOnly'],'dllSha256':sdk['dllSha256'],'sdkIdentityMatches':identity.get('sha256')==sdk['dllSha256'],'lostEvents':e['lostEvents'],'lostBuffers':e['lostBuffers'],'recordRawOwnershipPass':rawok,'sdkMicrophoneAttempts':len(sdkmic),'recordMicrophoneAttempts':len(raw),'aecRenderLoopbackClients':len(loop),'nativeSpeakerClients':len(speaker),'zeroAdditionalSdkMicPass':zero,'recordRawAudit':record,'clients':clients,'videoSource':r.get('videoSource','synthetic; physical camera unvalidated'),'captureStarts':r['captureStarts'],'phases':[{'name':q['name'],'rawBytesDelta':q['end']['rawBytes']-q['start']['rawBytes'],'cameraFramesDelta':q['end']['cameraFrames']-q['start']['cameraFrames'],'injectedAudioBytesDelta':q['end']['injectedAudioBytes']-q['start']['injectedAudioBytes'],'peerSamplesDelta':q['peerEnd']['samples']-q['peerStart']['samples']} for q in r['phases']],'endpointVolumeMuteUnchanged':(a.trial/'volume-before.txt').read_bytes()==(a.trial/'volume-after.txt').read_bytes(),'errors':r['errors'],'inputSha256':e['inputSha256']}
a.output.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ['clients','phases','inputSha256']}))
